CREATE EXTENSION IF NOT EXISTS timescaledb;
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS exchange_metadata(exchange text PRIMARY KEY, symbol text NOT NULL, coverage jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS contract_specs(exchange text NOT NULL, effective_at timestamptz NOT NULL, contract_btc double precision NOT NULL CHECK(contract_btc>0), spec jsonb NOT NULL, PRIMARY KEY(exchange,effective_at));
CREATE TABLE IF NOT EXISTS maintenance_margin_brackets(exchange text NOT NULL, effective_at timestamptz NOT NULL, tier integer NOT NULL, floor double precision NOT NULL, cap double precision NOT NULL, mmr double precision NOT NULL, deduction double precision NOT NULL DEFAULT 0, raw jsonb NOT NULL, PRIMARY KEY(exchange,effective_at,tier));
CREATE TABLE IF NOT EXISTS candles(ts timestamptz NOT NULL, exchange text NOT NULL, kind text NOT NULL, interval_s integer NOT NULL, o double precision NOT NULL, h double precision NOT NULL,l double precision NOT NULL,c double precision NOT NULL, volume double precision NOT NULL DEFAULT 0, buy_volume double precision, quote_volume double precision, complete boolean NOT NULL DEFAULT true, PRIMARY KEY(ts,exchange,kind,interval_s), CHECK(h>=l),CHECK(volume>=0));
SELECT create_hypertable('candles','ts',if_not_exists=>true,chunk_time_interval=>INTERVAL '7 days');
CREATE TABLE IF NOT EXISTS open_interest(ts timestamptz NOT NULL,exchange text NOT NULL, native double precision NOT NULL CHECK(native>=0), btc double precision NOT NULL, usd double precision, provenance text NOT NULL, raw jsonb NOT NULL, PRIMARY KEY(ts,exchange));
SELECT create_hypertable('open_interest','ts',if_not_exists=>true,chunk_time_interval=>INTERVAL '7 days');
CREATE TABLE IF NOT EXISTS funding_ratios(ts timestamptz NOT NULL,exchange text NOT NULL,kind text NOT NULL,value double precision NOT NULL,raw jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(ts,exchange,kind));
SELECT create_hypertable('funding_ratios','ts',if_not_exists=>true);
CREATE TABLE IF NOT EXISTS aggregate_trades(ts timestamptz NOT NULL,exchange text NOT NULL,trade_id text NOT NULL,price double precision NOT NULL,quantity_native double precision NOT NULL,buy boolean NOT NULL,PRIMARY KEY(ts,exchange,trade_id));
SELECT create_hypertable('aggregate_trades','ts',if_not_exists=>true,chunk_time_interval=>INTERVAL '1 hour');
CREATE INDEX IF NOT EXISTS trades_exchange_ts ON aggregate_trades(exchange,ts DESC);
CREATE TABLE IF NOT EXISTS volume_profiles(ts timestamptz NOT NULL,exchange text NOT NULL,price double precision NOT NULL,volume_native double precision NOT NULL,buy_native double precision NOT NULL,PRIMARY KEY(ts,exchange,price));
SELECT create_hypertable('volume_profiles','ts',if_not_exists=>true,chunk_time_interval=>INTERVAL '7 days');
CREATE TABLE IF NOT EXISTS observed_liquidations(ts timestamptz NOT NULL,exchange text NOT NULL,event_id text NOT NULL,side text NOT NULL,quantity_btc double precision NOT NULL,price double precision NOT NULL,usd double precision NOT NULL,price_semantics text NOT NULL,raw jsonb NOT NULL,PRIMARY KEY(ts,exchange,event_id));
SELECT create_hypertable('observed_liquidations','ts',if_not_exists=>true);
CREATE TABLE IF NOT EXISTS ingestion_checkpoints(exchange text NOT NULL,feed text NOT NULL,cursor jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(exchange,feed));
CREATE TABLE IF NOT EXISTS feed_coverage(exchange text NOT NULL,feed text NOT NULL,first_ts timestamptz,last_ts timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL,detail jsonb NOT NULL DEFAULT '{}',PRIMARY KEY(exchange,feed));
CREATE TABLE IF NOT EXISTS model_versions(version text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),parameters jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS leverage_parameters(exchange text NOT NULL,side integer NOT NULL,effective_at timestamptz NOT NULL,weights jsonb NOT NULL,PRIMARY KEY(exchange,side,effective_at));
CREATE TABLE IF NOT EXISTS calibration_history(ts timestamptz NOT NULL,exchange text NOT NULL,alpha_before double precision NOT NULL,alpha_after double precision NOT NULL CHECK(alpha_after BETWEEN .01 AND .15),observed_usd double precision NOT NULL,predicted_usd double precision NOT NULL,eligible boolean NOT NULL,reason text NOT NULL,window_end timestamptz NOT NULL,PRIMARY KEY(ts,exchange));
CREATE TABLE IF NOT EXISTS heatmap_snapshots(ts timestamptz NOT NULL,exchange text NOT NULL,model_version text NOT NULL,grid_start double precision NOT NULL,grid_n integer NOT NULL,mark double precision NOT NULL,matrix bytea NOT NULL,audit jsonb NOT NULL,PRIMARY KEY(ts,exchange,model_version));
SELECT create_hypertable('heatmap_snapshots','ts',if_not_exists=>true,chunk_time_interval=>INTERVAL '7 days');
CREATE TABLE IF NOT EXISTS leverage_tier_exposure(ts timestamptz NOT NULL,exchange text NOT NULL,side integer NOT NULL,leverage integer NOT NULL,btc double precision NOT NULL,usd double precision NOT NULL,PRIMARY KEY(ts,exchange,side,leverage));
SELECT create_hypertable('leverage_tier_exposure','ts',if_not_exists=>true);
CREATE TABLE IF NOT EXISTS clld_history(ts timestamptz NOT NULL,exchange text NOT NULL,long_usd double precision NOT NULL,short_usd double precision NOT NULL,clld_usd double precision NOT NULL,oscillator double precision NOT NULL,PRIMARY KEY(ts,exchange));
SELECT create_hypertable('clld_history','ts',if_not_exists=>true);
CREATE TABLE IF NOT EXISTS model_checkpoints(exchange text PRIMARY KEY,model_version text NOT NULL,ts timestamptz NOT NULL,meta jsonb NOT NULL,matrix bytea NOT NULL);
CREATE TABLE IF NOT EXISTS live_marks(exchange text PRIMARY KEY,ts timestamptz NOT NULL,price double precision NOT NULL);
CREATE TABLE IF NOT EXISTS stream_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,ts timestamptz NOT NULL DEFAULT now(),kind text NOT NULL,payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS stream_events_ts ON stream_events(ts);
CREATE INDEX IF NOT EXISTS candles_query ON candles(exchange,kind,interval_s,ts DESC);
CREATE INDEX IF NOT EXISTS oi_query ON open_interest(exchange,ts DESC);
INSERT INTO schema_migrations(version) VALUES('001') ON CONFLICT DO NOTHING;
